import {THREE,mesh,makeCharacters,poseCharacters} from './characters.js';
import {RoomEnvironment} from '/mascots/vendor/RoomEnvironment.js';
// Authored geometry is shared with the rendered sprites; images/video remain
// the complete low-power path when live graphics are unavailable.
const views=[];let graphics=true,raf=0,last=0,clock=0,helloAt=-10;
const clamp=THREE.MathUtils.clamp;
const activeMotion=()=>window.LemrixMotionState.enabled;
window.addEventListener('lemrix:hello',()=>{helloAt=clock;views.forEach(v=>v.dirty=true);});
function stage(canvas,span){if(!canvas||!graphics)return null;let renderer;try{const context=canvas.getContext('webgl2',{alpha:true,antialias:true,powerPreference:'high-performance'});if(!context){graphics=false;return null;}renderer=new THREE.WebGLRenderer({canvas,context,alpha:true,antialias:true});renderer.setClearColor(0,0);renderer.outputColorSpace=THREE.SRGBColorSpace;renderer.toneMapping=THREE.ACESFilmicToneMapping;renderer.toneMappingExposure=1.08;renderer.shadowMap.enabled=true;renderer.shadowMap.type=THREE.PCFSoftShadowMap;
const scene=new THREE.Scene(),camera=new THREE.OrthographicCamera(-4,4,3,-3,.1,40),world=new THREE.Group();scene.add(world);const env=new RoomEnvironment(),pmrem=new THREE.PMREMGenerator(renderer);scene.environment=pmrem.fromScene(env,.05).texture;scene.environmentIntensity=.38;env.dispose();pmrem.dispose();scene.add(new THREE.HemisphereLight('#bdd8eb','#8b7d85',2));const light=new THREE.DirectionalLight('#ffe7be',3.7);light.position.set(-3,6,5);light.castShadow=true;light.shadow.mapSize.set(1024,1024);Object.assign(light.shadow.camera,{left:-4,right:4,top:5,bottom:-3});light.shadow.normalBias=.035;light.shadow.bias=-.0002;scene.add(light);const rim=new THREE.DirectionalLight('#a6d5ee',2.1);rim.position.set(4,4,-4);scene.add(rim);
const pair=makeCharacters(world),host=canvas.parentElement,v={canvas,host,renderer,scene,camera,world,pair,visible:false,dirty:true,pose:null,failed:false};const resize=()=>{const r=canvas.getBoundingClientRect();if(!r.width||!r.height)return;renderer.setPixelRatio(Math.min(devicePixelRatio,innerWidth<761?1.4:1.7));renderer.setSize(r.width,r.height,false);const a=r.width/r.height;Object.assign(camera,{left:-span*a/2,right:span*a/2,top:span/2,bottom:-span/2});camera.updateProjectionMatrix();v.dirty=true;};new IntersectionObserver(e=>{v.visible=e[0].isIntersecting;v.dirty=true;},{rootMargin:'70px'}).observe(canvas);new ResizeObserver(resize).observe(canvas);resize();canvas.addEventListener('webglcontextlost',e=>{e.preventDefault();v.failed=true;host.classList.remove('has-webgl');window.dispatchEvent(new Event('lemrix:graphics-ready'));});views.push(v);return v;}catch{renderer?.dispose();graphics=false;return null;}}
function makeCard(){const v=stage(document.querySelector('#card-duo-canvas'),3.35);if(!v)return;const {pair,camera,scene}=v;pair.cookd.root.position.set(-.82,0,0);pair.lemrix.root.position.set(.83,0,0);camera.position.set(2.2,2.3,8.5);camera.lookAt(0,1.4,0);mesh(new THREE.PlaneGeometry(20,20),new THREE.ShadowMaterial({opacity:.19}),scene,[0,.065,0],null,false).rotation.x=-Math.PI/2;v.pose=t=>{poseCharacters(pair,t,{facing:Math.PI});const p=clamp((t-helloAt)/1.7,0,1),wave=Math.sin(p*Math.PI);pair.cookd.arms[0].rotation.z=-wave*.8;pair.lemrix.arms[1].rotation.z=wave*.72;pair.lemrix.arms[1].rotation.x=Math.sin(p*Math.PI*8)*wave*.12;};}
function loop(now){raf=requestAnimationFrame(loop);const dt=Math.min((now-last)/1000||0,.05);last=now;if(document.hidden||document.querySelector('dialog[open]:not(#search-dialog)'))return;const moving=activeMotion();if(moving)clock+=dt;for(const v of views){if(!v.visible||v.failed)continue;if(!moving&&!v.dirty)continue;try{v.pose?.(clock);v.renderer.render(v.scene,v.camera);if(!v.host.classList.contains('has-webgl')){v.host.classList.add('has-webgl');window.dispatchEvent(new Event('lemrix:graphics-ready'));}v.dirty=false;}catch{v.failed=true;v.host.classList.remove('has-webgl');v.renderer.dispose();window.dispatchEvent(new Event('lemrix:graphics-ready'));}}}
function init(){makeCard();if(views.length)raf=requestAnimationFrame(loop);}if(document.readyState==='loading')document.addEventListener('DOMContentLoaded',init,{once:true});else init();window.addEventListener('lemrix:motion-change',()=>views.forEach(v=>v.dirty=true));window.addEventListener('pagehide',e=>{cancelAnimationFrame(raf);if(!e.persisted)views.forEach(v=>v.renderer.dispose());});window.addEventListener('pageshow',e=>{if(!e.persisted||!views.length)return;last=performance.now();views.forEach(v=>v.dirty=true);raf=requestAnimationFrame(loop);});
